#!/bin/bash
# =============================================================================
# distill_qwen3.sh
# Distill datasets using Qwen/Qwen3-0.6B as the teacher model.
#
# For each conversation, every assistant turn is regenerated by the model.
# Multi-turn: previously distilled assistant responses feed into later turns.
#
# Usage:
#   bash distill_qwen3.sh --all                        # distill all datasets
#   bash distill_qwen3.sh --data ii_7M_instruct.jsonl  # distill one dataset
#   bash distill_qwen3.sh --all --sample 10            # distill 10 examples each
#   bash distill_qwen3.sh --data task_0.2M_instruct.jsonl --sample 1  # test run
#   bash distill_qwen3.sh --data-dir /path/to/datasets  # specify data directory
#
# Input files (read from ../ relative to this script):
#   ii_7M_instruct.jsonl, ii_gen_1.4M_instruct.jsonl, tulu_0.6M_instruct.jsonl,
#   am_1.4M_instruct.jsonl, task_0.2M_instruct.jsonl, ii_1.5M_base.jsonl
#
# Output files (written to the same directory):
#   ii_7M_instruct_distill.jsonl, ii_gen_1.4M_instruct_distill.jsonl,
#   tulu_distill.jsonl, am_1.4M_instruct_distill.jsonl,
#   task_0.2M_instruct_distill.jsonl, ii_1.5M_base_distill.jsonl
# =============================================================================

set -e

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
DATA_DIR="/path/to/"

VALID_DATASETS=(
    ii_7M_instruct.jsonl
    ii_gen_1.4M_instruct.jsonl
    tulu_0.6M_instruct.jsonl
    am_1.4M_instruct.jsonl
    task_0.2M_instruct.jsonl
    ii_1.5M_base.jsonl
)

# -----------------------------------------------------------------------------
# Parse arguments
# -----------------------------------------------------------------------------
DO_ALL=false
SELECTED_DATASETS=()
SAMPLE=0

while [[ $# -gt 0 ]]; do
    case "$1" in
        --all)
            DO_ALL=true
            shift
            ;;
        --data-dir)
            if [[ -z "$2" ]]; then
                echo "Error: --data-dir requires a directory path."
                exit 1
            fi
            DATA_DIR="$2"
            shift 2
            ;;
        --data)
            if [[ -z "$2" ]]; then
                echo "Error: --data requires a dataset name."
                echo "Valid options: ${VALID_DATASETS[*]}"
                exit 1
            fi
            SELECTED_DATASETS+=("$2")
            shift 2
            ;;
        --sample)
            if [[ -z "$2" ]]; then
                echo "Error: --sample requires a number."
                exit 1
            fi
            SAMPLE="$2"
            shift 2
            ;;
        *)
            echo "Unknown option: $1"
            echo "Usage: bash distill_qwen3.sh [--all] [--data <name>] [--sample N] [--data-dir <path>]"
            echo "Valid dataset names: ${VALID_DATASETS[*]}"
            exit 1
            ;;
    esac
done

# Default to --all
if [[ "$DO_ALL" == false && ${#SELECTED_DATASETS[@]} -eq 0 ]]; then
    DO_ALL=true
fi

# Validate selected datasets
for ds in "${SELECTED_DATASETS[@]}"; do
    found=false
    for valid in "${VALID_DATASETS[@]}"; do
        if [[ "$ds" == "$valid" ]]; then
            found=true
            break
        fi
    done
    if [[ "$found" == false ]]; then
        echo "Error: Invalid dataset '$ds'."
        echo "Valid dataset names: ${VALID_DATASETS[*]}"
        exit 1
    fi
done

mkdir -p "$DATA_DIR"

echo "============================================"
echo " Qwen3-0.6B Dataset Distillation"
echo " Data directory: $DATA_DIR"
echo "============================================"

# Check dependencies
echo ""
echo "Checking Python dependencies..."
pip install -q torch transformers tqdm 2>&1 | tail -1
echo "  Dependencies ready."

# Build python arguments
PY_ARGS="--data_dir $DATA_DIR"
if [[ "$DO_ALL" == true ]]; then
    PY_ARGS="$PY_ARGS --all"
else
    for ds in "${SELECTED_DATASETS[@]}"; do
        PY_ARGS="$PY_ARGS --data $ds"
    done
fi
if [[ "$SAMPLE" -gt 0 ]]; then
    PY_ARGS="$PY_ARGS --sample $SAMPLE"
fi

echo ""
echo "Running: python distill_qwen3.py $PY_ARGS"
echo ""

python "$SCRIPT_DIR/distill_qwen3.py" $PY_ARGS

echo ""
echo "============================================"
echo "Distillation finished."
echo "Output files in: $DATA_DIR"
echo "============================================"
